// Local Expo config plugin: signs Android release builds with a real keystore.
//
// android/ is generated by `expo prebuild`, so edits to android/app/build.gradle are lost on
// every prebuild. This plugin re-applies them each time:
//   1. adds a `release` signingConfig that reads DELIVEROO_KEYSTORE_PATH, DELIVEROO_KEYSTORE_PASSWORD,
//      DELIVEROO_KEY_ALIAS and DELIVEROO_KEY_PASSWORD from the environment;
//   2. makes buildTypes.release use it instead of the debug keystore;
//   3. fails the Gradle build with a clear message if a release task runs without those variables.
// There is deliberately no fallback to the debug keystore.
const { withAppBuildGradle } = require('expo/config-plugins');

const MARKER = '// [withAndroidReleaseSigning]';

const SIGNING_CONFIG_BLOCK = `
        release {
            ${MARKER}
            def releaseKeystorePath = System.getenv('DELIVEROO_KEYSTORE_PATH')
            if (releaseKeystorePath) {
                storeFile new File(releaseKeystorePath)
                storePassword System.getenv('DELIVEROO_KEYSTORE_PASSWORD')
                keyAlias System.getenv('DELIVEROO_KEY_ALIAS')
                keyPassword System.getenv('DELIVEROO_KEY_PASSWORD')
            }
        }`;

const RELEASE_GUARD = `
${MARKER} refuse to build a release without the signing environment variables.
gradle.taskGraph.whenReady { graph ->
    def releaseTaskNames = ['assembleRelease', 'bundleRelease', 'packageRelease', 'validateSigningRelease']
    def building = graph.allTasks.any { it.project == project && releaseTaskNames.contains(it.name) }
    if (!building) return

    def required = ['DELIVEROO_KEYSTORE_PATH', 'DELIVEROO_KEYSTORE_PASSWORD', 'DELIVEROO_KEY_ALIAS', 'DELIVEROO_KEY_PASSWORD']
    def missing = required.findAll { !System.getenv(it) }
    if (!missing.isEmpty()) {
        throw new GradleException('Release signing is not configured. Set these environment variables before building a release: ' + missing.join(', ') + '. The debug keystore is never used for release builds.')
    }
    def keystore = new File(System.getenv('DELIVEROO_KEYSTORE_PATH'))
    if (!keystore.isFile()) {
        throw new GradleException('DELIVEROO_KEYSTORE_PATH does not point to an existing file: ' + keystore)
    }
}
`;

function applyReleaseSigning(contents) {
  if (contents.includes(MARKER)) return contents; // already applied

  // 1. Add the release signingConfig right after the debug one.
  const signingConfigs = /signingConfigs\s*\{\s*debug\s*\{[^}]*\}/;
  if (!signingConfigs.test(contents)) {
    throw new Error('withAndroidReleaseSigning: could not find signingConfigs { debug { ... } } in app/build.gradle');
  }
  let next = contents.replace(signingConfigs, (match) => match + SIGNING_CONFIG_BLOCK);

  // 2. Point buildTypes.release at it.
  const releaseBuildType = /(buildTypes\s*\{[\s\S]*?\brelease\s*\{[\s\S]*?)signingConfig\s+signingConfigs\.debug/;
  if (!releaseBuildType.test(next)) {
    throw new Error('withAndroidReleaseSigning: could not find "signingConfig signingConfigs.debug" in buildTypes.release');
  }
  next = next.replace(releaseBuildType, '$1signingConfig signingConfigs.release');

  // 3. Fail fast when the environment is incomplete.
  return next + RELEASE_GUARD;
}

module.exports = function withAndroidReleaseSigning(config) {
  return withAppBuildGradle(config, (cfg) => {
    cfg.modResults.contents = applyReleaseSigning(cfg.modResults.contents);
    return cfg;
  });
};

module.exports.applyReleaseSigning = applyReleaseSigning;
